// SPDX-License-Identifier: CC0-1.0
#include HEADER
#include <chrono>
#include <cstdint>
#include <cstdlib>
#include <iostream>
#include <iomanip>
#include <random>
#include <string>
#include <vector>
template<class T, class C=geo::DefaultCalc<T>> void run(std::size_t n, int loops, int shape) {
    std::mt19937_64 rng(29157);
    std::vector<geo::Point<T,C>> poly(n);
    for(std::size_t i=0;i<n;++i) {
        auto x=std::int64_t(rng()%2000001)-1000000;
        auto y=std::int64_t(rng()%2000001)-1000000;
        if(shape==1){x=std::int64_t(i);y=std::int64_t(i%2)*1000000;}
        if(shape==2){x*=1000000;y*=1000000;}
        poly[i]={T(x),T(y)};
    }
    long double checksum=0;
    auto start=std::chrono::steady_clock::now();
    for(int k=0;k<loops;++k) {
        if(n)poly[0].x=T(k%10);
        checksum+=geo::area(poly);
    }
    auto end=std::chrono::steady_clock::now();
    std::cout<<std::chrono::duration<double,std::milli>(end-start).count()<<' '<<std::setprecision(22)<<checksum<<'\n';
}
int main(int argc,char**argv) {
 if(argc!=6)return 1;
 auto n=std::strtoull(argv[1],nullptr,10);int loops=std::atoi(argv[2]),shape=std::atoi(argv[3]);std::string type=argv[4],calc=argv[5];
 if(type=="integer"&&calc=="default")run<std::int64_t>(n,loops,shape);
 else if(type=="integer")run<std::int64_t,std::int64_t>(n,loops,shape);
 else if(type=="double")run<double>(n,loops,shape);
 else run<long double>(n,loops,shape);
}

